findings.suggestion:
Tighten has_read to ensure the read attribute is callable:

def has_read(obj: Any) -> TypeIs[SupportsRead[str | bytes]]:
    """Check if obj supports read, including __getattr__ based proxies."""
    if isinstance(obj, SupportsRead):
        return True
    try:
        read = obj.read
    except Exception:
        return False
    return callable(read)
